-- The staff directory sync of the identity module (Phase 1 slice 1.5; ADR-0022 decision 2).
-- Generated by prisma migrate dev --create-only, then the hand-written CHECKs, grants and
-- row-level security at the end.
-- CreateTable
CREATE TABLE "identity"."directory_sync" (
    "tenant_id" VARCHAR(32) NOT NULL,
    "interval_minutes" SMALLINT NOT NULL,
    "last_started_at" TIMESTAMPTZ(3),
    "last_outcome" VARCHAR(16),
    "last_finished_at" TIMESTAMPTZ(3),
    "accounts_checked" INTEGER NOT NULL,
    "accounts_disabled" INTEGER NOT NULL,
    "accounts_enabled" INTEGER NOT NULL,
    "version" INTEGER NOT NULL,
    "updated_at" TIMESTAMPTZ(3) NOT NULL,

    CONSTRAINT "directory_sync_pkey" PRIMARY KEY ("tenant_id")
);


-- Hand-written: integrity backstops Prisma cannot express.
ALTER TABLE "identity"."directory_sync"
  ADD CONSTRAINT "directory_sync_tenant_id_check" CHECK ("tenant_id" ~ '^[a-z][a-z0-9-]{1,31}$'),
  ADD CONSTRAINT "directory_sync_interval_minutes_check" CHECK ("interval_minutes" BETWEEN 1 AND 60),
  ADD CONSTRAINT "directory_sync_last_outcome_check" CHECK ("last_outcome" IS NULL OR "last_outcome" IN ('completed', 'failed', 'halted')),
  ADD CONSTRAINT "directory_sync_counts_check" CHECK ("accounts_checked" >= 0 AND "accounts_disabled" >= 0 AND "accounts_enabled" >= 0),
  ADD CONSTRAINT "directory_sync_version_check" CHECK ("version" >= 1);

-- Grants. The group role "phoenix_app" is created by the cluster bootstrap, never by a
-- migration.
GRANT SELECT, INSERT, UPDATE ("interval_minutes", "last_started_at", "last_outcome", "last_finished_at", "accounts_checked", "accounts_disabled", "accounts_enabled", "version", "updated_at") ON TABLE "identity"."directory_sync" TO "phoenix_app";

-- Row-level security (ADR-0002), enabled and forced, with the reference policy.
ALTER TABLE "identity"."directory_sync" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "identity"."directory_sync" FORCE ROW LEVEL SECURITY;
CREATE POLICY "directory_sync_tenant_isolation" ON "identity"."directory_sync"
  AS PERMISSIVE FOR ALL TO "phoenix_app"
  USING ("tenant_id" = "platform"."current_tenant_id"())
  WITH CHECK ("tenant_id" = "platform"."current_tenant_id"());
